#include <iostream>

// Giai thuong lap (Iterative factorial)
unsigned long long tinhGiaiThuaLap(int n) {
    unsigned long long kq = 1;
    for (int i = 1; i <= n; ++i) {
        kq *= static_cast<unsigned long long>(i);
    }
    return kq;
}

// Giai thuat de qui (Recursive factorial)
unsigned long long tinhGiaiThuaDeQui(int n) {
    if (n <= 0) {
        return 1;
    }
    return tinhGiaiThuaDeQui(n - 1) * static_cast<unsigned long long>(n);
}

int main() {
    int n = 0;
    if (std::cin >> n) {
        std::cout << "Lap: " << n << "! = " << tinhGiaiThuaLap(n) << "\n";
        std::cout << "De qui: " << n << "! = " << tinhGiaiThuaDeQui(n) << "\n";
    }
    return 0;
}

#include <iostream>

// UCLN su dung phep tru theo dung giao trinh (kem return hop le trong C++17)
int UCLN(int a, int b) {
    if (a == b) {
        return a;
    }
    if (a < b) {
        return UCLN(a, b - a);
    }
    return UCLN(a - b, b);
}

// Tinh so hang Fibonacci theo giao trinh: f(0)=1, f(1)=1, f(n)=f(n-1)+f(n-2)
long long Fib(int n) {
    if (n == 0 || n == 1) {
        return 1;
    }
    return Fib(n - 1) + Fib(n - 2);
}

// Tinh vi tri trung gian cho bai toan thap Ha Noi (trang 128)
int timViTriTrungGian(int di, int den) {
    return 6 - di - den;
}

int main() {
    int a = 0, b = 0, n = 0;
    if (std::cin >> a >> b >> n) {
        std::cout << "UCLN(" << a << ", " << b << ") = " << UCLN(a, b) << "\n";
        std::cout << "Fib(" << n << ") = " << Fib(n) << "\n";
        std::cout << "Vi tri trung gian giua 1 va 2 la: " << timViTriTrungGian(1, 2) << "\n";
    }
    return 0;
}
